{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "urn:umf:core:key-transition:1.0.0",
  "title": "Explicit Key envelope transition receipts",
  "$defs": {
    "residual": {
      "type": "object",
      "required": [
        "path",
        "value",
        "reason"
      ],
      "additionalProperties": false,
      "properties": {
        "path": {
          "type": "string",
          "pattern": "^/modules/[0-9]+/elements/[0-9]+/(key|keys|members)$"
        },
        "value": {},
        "reason": {
          "const": "Legacy key, keys and members are opaque; no ownership or identity inferred"
        }
      }
    },
    "upgrade": {
      "type": "object",
      "required": [
        "operation",
        "version",
        "source",
        "target",
        "residuals"
      ],
      "additionalProperties": false,
      "properties": {
        "operation": {
          "const": "upgrade-key-envelope"
        },
        "version": {
          "const": "1.0.0"
        },
        "source": {
          "$ref": "urn:umf:core:0.5.0"
        },
        "target": {
          "$ref": "urn:umf:core:0.6.0"
        },
        "residuals": {
          "type": "array",
          "items": {
            "$ref": "#/$defs/residual"
          }
        }
      }
    },
    "rollback": {
      "type": "object",
      "required": [
        "operation",
        "version",
        "source",
        "target",
        "receipt",
        "reason"
      ],
      "additionalProperties": false,
      "properties": {
        "operation": {
          "const": "rollback-key-envelope"
        },
        "version": {
          "const": "1.0.0"
        },
        "source": {
          "$ref": "urn:umf:core:0.6.0"
        },
        "target": {
          "$ref": "urn:umf:core:0.5.0"
        },
        "receipt": {
          "$ref": "#/$defs/upgrade"
        },
        "reason": {
          "const": "Original envelope restored; all subsequent content retained in source, not applied to legacy target"
        }
      }
    }
  },
  "oneOf": [
    {
      "$ref": "#/$defs/upgrade"
    },
    {
      "$ref": "#/$defs/rollback"
    }
  ],
  "description": "Schema validation establishes receipt structure only. Rollback verifies a receipt by recomputing the upgrade from its retained source, validates current candidate semantics and identity, restores the exact original envelope and separately retains the entire current one."
}
